from pathlib import Path
from playwright.sync_api import sync_playwright
with sync_playwright() as p:
 b=p.chromium.launch(headless=True,args=['--no-sandbox']);page=b.new_page(viewport={'width':1366,'height':768});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.on('dialog',lambda d:d.accept());page.goto('http://localhost:3000');page.wait_for_selector('#playAdventure');page.click('#playAdventure');page.wait_for_function("state==='play'")
 formations=page.evaluate('''()=>{const out={};stage=0;world=worlds[0];wave=1;out.gentle=makeSchedule().every(d=>d.pattern<4);stage=3;world=worlds[3];wave=3;const list=makeSchedule();out.spider=list.some(d=>d.pattern===6);stage=0;world=worlds[0];out.bat=makeSchedule().some(d=>d.pattern===4);stage=1;world=worlds[1];out.ghost=makeSchedule().some(d=>d.pattern===5);return out}''');assert all(formations.values()),formations
 choice=page.evaluate('''()=>{stage=2;world=worlds[2];wave=4;upgrades.fire=0;upgrades.poison=0;drops=[];dropUpgrade(400,500);const pair=drops.filter(d=>d.choiceId);const before=upgrades[pair[0].key],other=upgrades[pair[1].key];collectUpgrade(pair[0]);collectUpgrade(pair[1]);return{pair:pair.length===2,exclusive:pair[1].taken&&upgrades[pair[1].key]===other,one:upgrades[pair[0].key]===before+1}}''');assert all(choice.values()),choice
 events=page.evaluate('''()=>{const results=[];for(stage=0;stage<5;stage++){world=worlds[stage];obstacles=[];gates=[];enemies=[];drops=[];Adventure.tick(20);transition=0;const ok=Encounters.startEvent();player.x=400;player.y=780;player.inv=99;Encounters.tick(2);drawGame();results.push(ok)}return results}''');assert all(events),events
 metrics=page.evaluate('''()=>{stage=0;world=worlds[0];wave=1;enemies=[{x:400,y:650,hp:30,max:30,r:20,age:0}];player.x=400;player.y=780;Arsenal.active.spell='pulse';Arsenal.active.cooldown=0;const before=Journey.run.stats.specialDamage||0;Arsenal.cast();const damage=(Journey.run.stats.specialDamage||0)-before;player.shield=0;player.inv=0;lives=3;hurt(25,'un projectile vampire');return {damage,source:Journey.run.stats.danger_shot}}''');assert metrics['damage']==10 and metrics['source']==1,metrics
 page.evaluate('pauseScreen()');page.click('#pauseSettings');page.wait_for_selector('#opt-music')
 for selector in ['#opt-scares','#opt-shake','#opt-reduced','#bulletContrast','#effectLevel','#flashSafe','#autoPause']:assert not page.locator(selector).count(),selector
 page.evaluate("prefs.autoPause=false;state='play';hideOverlay();window.dispatchEvent(new Event('blur'))");assert page.evaluate("state==='pause'")
 page.evaluate("state='play';end(false)");page.wait_for_selector('#flightAnalysis');assert 'Projectiles' in page.inner_text('#flightAnalysis');page.screenshot(path=str(Path(__file__).parent/'encounters-result.png'),full_page=True);page.click('#practiceResultBoss');page.wait_for_function('Adventure.training');assert page.evaluate("enemies[0].boss&&enemies[0].kind==='pumpkin'");page.click('#exitLab');assert not errors,errors
 print('OK : formations, premier vol doux, reliques exclusives, cinq événements, dégâts de sort/causes, réglages neutres, pause auto commune, bilan et laboratoire ciblé. Aucune erreur JS.');b.close()
